insert into public.questions (id, paper_id, topic_id, stem, image_url, explanation, position)
values ('ab74b5a3-5e93-5ef0-9a4c-f42ee7267e34', '69ccfee9-54b3-558c-86ae-36a41d314aad', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Sine, Cosine and Tangent'),
        'In triangle $PQR$, $\angle PQR = 90°$, $|PQ| = 8$ cm and $|QR| = 15$ cm. Find $\sin R$.',
        'https://wasscetutor.com/questions/mathematics/maths-trig-01.svg?v=e6cefd9be5',
        '$|PR| = \sqrt{8^{2} + 15^{2}} = \sqrt{289} = 17$ cm.

$\sin R = \dfrac{\text{opposite}}{\text{hypotenuse}} = \dfrac{|PQ|}{|PR|} = \dfrac{8}{17}$

**Why the other options are wrong**

- $\dfrac{8}{15}$: That is $\tan R$ (opposite ÷ adjacent). Sine is opposite ÷ hypotenuse.
- $\dfrac{15}{17}$: That is $\cos R$. For $\sin R$ use the side opposite $R$, which is $PQ$.
- $\dfrac{15}{8}$: You divided the adjacent side by the opposite side.',
        1)
