insert into public.questions (id, paper_id, topic_id, stem, image_url, explanation, position)
values ('6572ea9d-1d27-5d12-8e21-af61e02d2027', '69ccfee9-54b3-558c-86ae-36a41d314aad', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Sine, Cosine and Tangent'),
        'Without using tables or a calculator, evaluate $\sin 60° \cos 30° + \cos 60° \sin 30°$.',
        null,
        '$\sin 60° = \cos 30° = \dfrac{\sqrt{3}}{2}$ and $\cos 60° = \sin 30° = \dfrac{1}{2}$.

$\dfrac{\sqrt{3}}{2} \times \dfrac{\sqrt{3}}{2} + \dfrac{1}{2} \times \dfrac{1}{2} = \dfrac{3}{4} + \dfrac{1}{4} = 1$

**Why the other options are wrong**

- $\dfrac{1}{2}$: You subtracted the second product: $\dfrac{3}{4} - \dfrac{1}{4}$.
- $\dfrac{3}{4}$: You left out the second product, $\cos 60° \sin 30° = \dfrac{1}{4}$.
- $\dfrac{\sqrt{3}}{2}$: That is only $\sin 60°$.',
        2)
