insert into public.questions (id, paper_id, topic_id, stem, image_url, explanation, position)
values ('8f8a1d32-38a5-5a73-ae5c-327b2b812a8b', '69ccfee9-54b3-558c-86ae-36a41d314aad', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Sine, Cosine and Tangent'),
        'Find the values of $\theta$ between 0° and 360° for which $\cos\theta = -\dfrac{1}{2}$.',
        null,
        'The acute angle with $\cos = \dfrac{1}{2}$ is 60°. Cosine is negative in the second and third quadrants:

$\theta = 180° - 60° = 120°$ or $\theta = 180° + 60° = 240°$.

**Why the other options are wrong**

- $60°$ and $300°$: Those solve $\cos\theta = +\dfrac{1}{2}$. Cosine is negative in the second and third quadrants.
- $150°$ and $210°$: Those solve $\cos\theta = -\dfrac{\sqrt{3}}{2}$. The acute angle whose cosine is $\dfrac{1}{2}$ is 60°, not 30°.
- $210°$ and $330°$: Those solve $\sin\theta = -\dfrac{1}{2}$.',
        3)
