insert into public.questions (id, paper_id, topic_id, stem, image_url, explanation, position)
values ('494e39a5-242d-5cc3-9d83-7abb57583f0e', 'd61286c0-e727-52d1-b7af-a1519069ad03', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Angles of Elevation and Depression'),
        'From the top $P$ of a building, the angle of depression of a car $Q$ on the level ground is 32°. What is the angle of elevation of $P$ from $Q$?',
        null,
        'The horizontal line through $P$ is parallel to the level ground. The angle of depression at $P$ and the angle of elevation at $Q$ are alternate angles between these parallel lines, so they are equal: 32°.

**Why the other options are wrong**

- 58°: $90° - 32°$ is the angle with the vertical. Angles of elevation and depression are measured from the horizontal.
- 90°: The building is vertical, but the angle of elevation is measured from the horizontal ground at $Q$ up to the line $QP$.
- 148°: $180° - 32°$: the two angles are alternate angles, so they are equal.',
        5)
