values ('95d26ad2-1ab4-5645-89ff-ae43dbdbebef', 'ea7c6aff-ada1-52b9-806b-5972ef98b929', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Modular Arithmetic'),
        'Evaluate $7 \times 6 \pmod{5}$.',
        null,
        '$7 \times 6 = 42 = 8 \times 5 + 2$, so $7 \times 6 \equiv 2 \pmod{5}$.

**Why the other options are wrong**

- $3$: You added: $7 + 6 = 13 \equiv 3$. The question asks for $7 \times 6$.
- $8$: 8 is the quotient: $42 = 8 \times 5 + 2$. The answer is the remainder.
- $42$: Reduce 42 modulo 5: the answer must be a whole number from 0 to 4.',
        1)
