insert into public.questions (id, paper_id, topic_id, stem, image_url, explanation, position)
values ('4ad5c9c1-798c-53db-bf03-e2845c0c0872', 'ea7c6aff-ada1-52b9-806b-5972ef98b929', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Modular Arithmetic'),
        'Solve $2x + 3 \equiv 1 \pmod{5}$.',
        null,
        '$2x \equiv 1 - 3 = -2 \equiv 3 \pmod{5}$.

Try $x = 0, \ldots, 4$: $2 \times 4 = 8 \equiv 3$. So $x = 4$.

Check: $2(4) + 3 = 11 \equiv 1 \pmod{5}$. ✓

**Why the other options are wrong**

- $-1$: In modulo 5 the answer must be from 0 to 4. Add 5: $-1 + 5 = 4$.
- $1.5$: You solved $2x = 3$ as an ordinary equation. In modulo 5, try $x = 0, \ldots, 4$ until $2x$ leaves remainder 3.
- $2$: Sign slip: $2x \equiv 1 - 3$, not $1 + 3$.',
        5)
