insert into public.questions (id, paper_id, topic_id, stem, image_url, explanation, position)
values ('27fe7f1b-3e52-515d-a826-503c3bf61305', 'ac94586a-2927-5225-9209-929f56a32d39', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'mathematics' and t.name = 'Vectors'),
        'Given that $\mathbf{a} = \begin{pmatrix} 3 \\ -2 \end{pmatrix}$ and $\mathbf{b} = \begin{pmatrix} -1 \\ 4 \end{pmatrix}$, find $2\mathbf{a} - \mathbf{b}$.',
        null,
        '$2\mathbf{a} = \begin{pmatrix} 6 \\ -4 \end{pmatrix}$

$2\mathbf{a} - \mathbf{b} = \begin{pmatrix} 6 - (-1) \\ -4 - 4 \end{pmatrix} = \begin{pmatrix} 7 \\ -8 \end{pmatrix}$

**Why the other options are wrong**

- $\begin{pmatrix} 5 \\ 0 \end{pmatrix}$: You added $\mathbf{b}$ instead of subtracting it.
- $\begin{pmatrix} 5 \\ -8 \end{pmatrix}$: Sign slip in the top number: $6 - (-1) = 6 + 1 = 7$.
- $\begin{pmatrix} 4 \\ -6 \end{pmatrix}$: You forgot to double $\mathbf{a}$. That is $\mathbf{a} - \mathbf{b}$.',
        1)
